// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address keeper, uint256 t0, uint256 delta) public {
        vm.assume(keeper != address(0));
        t0 = bound(t0, 1, 10_000_000_000);
        delta = bound(delta, 0, 899); // strictly less than 15 minutes

        vm.prank(c.owner());
        c.setKeeper(keeper);

        vm.warp(t0);
        vm.prank(keeper);
        bool ok1; try c.executeBatchDeposit() { ok1 = true; } catch { ok1 = false; }
        ok1;

        vm.warp(t0 + delta);
        vm.prank(keeper);
        bool ok2; try c.executeBatchDeposit() { ok2 = true; } catch { ok2 = false; }

        if (ok1 && ok2) {
            assertTrue(false, "second executeBatchDeposit succeeded too soon");
        } else {
            assertTrue(true);
        }
    }
}
